export const createPost = (
  freeboardCreateRequest: FreeboardCreateRequest,
  signal?: AbortSignal,
) => {
  const formData = new FormData();
  formData.append(`category`, freeboardCreateRequest.category);
  formData.append(`title`, freeboardCreateRequest.title);
  formData.append(`content`, freeboardCreateRequest.content);
  if (freeboardCreateRequest.images !== undefined) {
    freeboardCreateRequest.images.forEach((value) =>
      formData.append(`images`, value),
    );
  }

  return customInstance<FreeboardCreateResponse>({
    url: `/community/freeboard`,
    method: 'POST',
    headers: { 'Content-Type': 'multipart/form-data' },
    data: formData,
    signal,
  });
};

