/**
 * 작성한 게시글을 수정합니다.

**수정 가능 항목:**
- 제목
- 내용
- 카테고리
- 이미지 (기존 이미지 교체 가능)

**권한:** 작성자 본인만 수정 가능

 * @summary 자유게시판 글 수정
 */
export const updatePost = (
  freeboardId: number,
  freeboardUpdateRequest: FreeboardUpdateRequest,
) => {
  const formData = new FormData();
  if (freeboardUpdateRequest.category !== undefined) {
    formData.append(`category`, freeboardUpdateRequest.category);
  }
  if (freeboardUpdateRequest.title !== undefined) {
    formData.append(`title`, freeboardUpdateRequest.title);
  }
  if (freeboardUpdateRequest.content !== undefined) {
    formData.append(`content`, freeboardUpdateRequest.content);
  }
  if (freeboardUpdateRequest.images !== undefined) {
    freeboardUpdateRequest.images.forEach((value) =>
      formData.append(`images`, value),
    );
  }
  if (freeboardUpdateRequest.deleteImageIds !== undefined) {
    freeboardUpdateRequest.deleteImageIds.forEach((value) =>
      formData.append(`deleteImageIds`, value.toString()),
    );
  }

  return customInstance<FreeboardCreateResponse>({
    url: `/community/freeboard/${freeboardId}`,
    method: 'PATCH',
    headers: { 'Content-Type': 'multipart/form-data' },
    data: formData,
  });
};

